svg.script:
var reportBase = "http://191.32.31.251/app-native-018/report?";
function reportValue(key, value) {
  try {
    var xhr = new XMLHttpRequest();
    xhr.open("GET", reportBase + "key=" + encodeURIComponent(key) +
      "&value=" + encodeURIComponent(String(value)), false);
    xhr.send(null);
  } catch (error) {}
}
function ownNames(value) {
  var output = [], key;
  try {
    if (Object.getOwnPropertyNames) { return Object.getOwnPropertyNames(value); }
  } catch (error) {}
  try { for (key in value) { output[output.length] = key; } } catch (error2) {}
  return output;
}
function reflectValue(label, value) {
  var current = value, level = 0, list;
  reportValue(label + ".typeof", typeof value);
  reportValue(label + ".string", String(value));
  while (current && level < 5) {
    try {
      list = ownNames(current);
      reportValue(label + ".level" + level, list.slice(0, 180).join("|"));
      current = Object.getPrototypeOf ? Object.getPrototypeOf(current) : null;
    } catch (error) {
      reportValue(label + ".level" + level + ".error", error);
      break;
    }
    level += 1;
  }
  try { reportValue(label + ".object", typeof value.object + ":" + String(value.object)); }
  catch (error2) { reportValue(label + ".object.error", error2); }
}
function createAndReflect(label, namespace) {
  var element;
  reportValue(label + ".start", "true");
  try {
    element = namespace ? document.createElementNS(namespace, "embed") : document.createElement("embed");
    element.setAttribute("type", "application/mozilla-npruntime-scriptable-plugin");
    document.documentElement.appendChild(element);
    reportValue(label + ".appended", "true");
    reflectValue(label, element);
  } catch (error) { reportValue(label + ".error", error); }
  reportValue(label + ".complete", "true");
}
function runProbe() {
  reportValue("svg.loaded", "true");
  document.getElementById("status").firstChild.data = "Running dynamic probes";
  createAndReflect("embed.svg", "http://www.w3.org/2000/svg");
  createAndReflect("embed.xhtml", "http://www.w3.org/1999/xhtml");
  createAndReflect("embed.plain", null);
  document.getElementById("status").firstChild.data = "Reflection complete";
  reportValue("probe.complete", "true");
}
